package com.andye.warmod.antiair.client;import com.andye.warmod.antiair.*;import com.andye.warmod.antiair.network.*;import java.util.UUID;import net.minecraft.world.phys.Vec3;public final class AntiAirVisualState{private final ClientboundAntiAirLaunchPayload launch;private AntiAirRoute route;private long routeLockTime;private AntiAirFlightPhase phase=AntiAirFlightPhase.IGNITION;public AntiAirVisualState(ClientboundAntiAirLaunchPayload p){launch=p;}public UUID id(){return launch.interceptorId();}public AntiAirMissileVariant variant(){return launch.variant();}public long seed(){return launch.visualSeed();}public AntiAirFlightPhase phase(){return phase;}public void lock(ClientboundAntiAirRouteLockPayload p){route=new AntiAirRoute(launch.burnoutPosition(),p.controlPoint1(),p.controlPoint2(),p.resolvedInterceptPosition(),p.interceptTicks());routeLockTime=p.routeLockGameTime();phase=AntiAirFlightPhase.INTERCEPT;}public void phase(ClientboundAntiAirPhasePayload p){phase=p.phase();}public Vec3 position(long time,double partial){double now=time+partial;if(route!=null&&now>=routeLockTime)return route.position(now-routeLockTime);double u=Math.max(0,Math.min(1,(now-launch.launchGameTime()-launch.ignitionTicks())/launch.boostTicks()));u=u*u*(3-2*u);return launch.launchPosition().lerp(launch.burnoutPosition(),u);}public Vec3 velocity(long time,double partial){return position(time,partial+.1).subtract(position(time,partial-.1)).scale(5);}public boolean thrust(){return phase!=AntiAirFlightPhase.FALLBACK&&phase!=AntiAirFlightPhase.SELF_DESTRUCT;}}